from six import string_types


class NasParser:
    """NasParser command class."""

    def __init__(self):
        """Nasparser helper class."""

    @staticmethod
    def parse(axiom):
        """
        Parse given string into dictionary.

        :param axiom:       text to parse
        :type axiom:        string
        :return:            parsed axiom
        :rtype:             dict
        """
        list_of_elements = axiom.split("\n")
        for element in list_of_elements:
            if NasParser._strip_unnecessary_characters_from_axiom(element) == "":
                list_of_elements.remove(element)

        return NasParser._parse(list_of_elements)

    @staticmethod
    def _strip(axiom):
        """
        Strip given axiom if possible.

        :param axiom:       text to parse
        :return:            parsed text
        """
        # if type(axiom) == str or type(axiom) == unicode:
        if isinstance(axiom, string_types):
            return axiom.strip()
        return axiom

    @staticmethod
    def _strip_unnecessary_characters_from_axiom(axiom):
        """
        Remove unnecessary characters from axiom e.g '{', '}', ':', ' '.

        :param axiom:   text to parse
        :type axiom:    string
        :return:        text without unnecessary characters
                        e.g "xxxx" if axiom = "    { xxxx }   "
        :rtype:         string
        """
        for c in "{}":
            if axiom.count("{") != axiom.count("}"):
                axiom = axiom.strip(c)
        for c in ": ":
            axiom = axiom.strip(c)

        if axiom and axiom[0] == "{" and axiom[-1] == "}":
            axiom = axiom[1:-1].strip()

        for c in "[]":
            if axiom.count("[") != axiom.count("]"):
                axiom = axiom.strip(c)

        if axiom and axiom[0] == "[" and axiom[-1] == "]":
            axiom = axiom[1:-1].strip()

        if axiom and axiom[0] == "'" and axiom[-1] == "'":
            axiom = axiom[1:-1].strip()

        axiom = axiom.replace("- ", "")
        return NasParser._strip(axiom)

    @staticmethod
    def _parse_element(axiom):
        """
        Create a dictionary from axiom.

        :param axiom:   text to parse
        :type axiom:    string
        :return:        dictionary created from the axiom where the key and value are separated by '='
                        e.g {abc:def}  if axiom = "abc = def"
                        If there is no '=' then key = axiom, value = None
                        e.g {abc:None} if axiom = "abc"
        :rtype:         dict
        """
        if ":" not in axiom:
            return {NasParser._strip_unnecessary_characters_from_axiom(axiom): None}
        else:
            value = NasParser._strip_unnecessary_characters_from_axiom(
                axiom.split(":")[1])
            if "," in value:
                value = value.split(", ")
            return {NasParser._strip_unnecessary_characters_from_axiom(
                axiom.split(":")[0]): value}

    @staticmethod
    def _number_of_spaces_before_axiom(axiom):
        """
        Count the number of spaces before the text.

        :param axiom:   text in which we are counting spaces e.g axiom = "     xxx"
        :type axiom:    string
        :return:        number of spaces before axiom e.g return 5 if axiom = "     xxx"
        :rtype:         int
        """
        return len(axiom) - len(axiom.lstrip())

    @staticmethod
    def _get_list_with_an_equal_number_of_spaces_preceding_element(list_of_elements):
        """
        Compare the number of spaces the first element with the next until the number of spaces reduced.

        :param list_of_elements:    list which may have a different number of spaces preceding element
        :type list_of_elements:     list
        :return:                    list in the number of spaces is not
                                    less than the number of spaces the first element
                                    ["   abc","   "   cde","      efg"]
                                    if list_of_elements =["   abc","   "   cde","      efg" ,"xxx" , ....]
        :rtype:                     list
        """
        for index, element in enumerate(list_of_elements[1:]):
            if NasParser._number_of_spaces_before_axiom(
                    list_of_elements[0]) > NasParser._number_of_spaces_before_axiom(
                    element):
                return list_of_elements[: index + 1]
        return list_of_elements

    @staticmethod
    def _parse(list_of_elements):
        r"""
        Parse given list of elements recursively.

        :param list_of_elements:    list of elements created by division of text separated '\n'
        :type list_of_elements:     list
        :return:                    parsed axiom
        :rtype:                     dict
        """
        dict_of_elements = {}
        for index, j_element in enumerate(list_of_elements):
            if index + 1 == len(list_of_elements) or index + 1 < len(list_of_elements) and \
                    NasParser._number_of_spaces_before_axiom(list_of_elements[index]) == \
                    NasParser._number_of_spaces_before_axiom(list_of_elements[index + 1]):

                dict_of_elements.update(NasParser._parse_element(j_element))
            else:
                dict_of_elements.update(
                    {
                        NasParser._strip_unnecessary_characters_from_axiom(
                            j_element): NasParser._parse(
                            NasParser._get_list_with_an_equal_number_of_spaces_preceding_element(
                                list_of_elements[index + 1:])
                        )
                    }
                )

                old_number_of_spaces = None
                for j, j_element in enumerate(list_of_elements[index + 1 + 1:]):
                    if NasParser._number_of_spaces_before_axiom(list_of_elements[
                                                                index + 1]) > NasParser._number_of_spaces_before_axiom(
                            j_element):
                        if not old_number_of_spaces:
                            old_number_of_spaces = j + 1
                        else:
                            dict_of_elements.update(NasParser._parse(list_of_elements[
                                                                     index + 1 + old_number_of_spaces: index + 1 + j + 1]))
                            old_number_of_spaces = j + 1
                if old_number_of_spaces:
                    dict_of_elements.update(NasParser._parse(list_of_elements[
                                                             index + 1 + old_number_of_spaces: index + 1 + len(
                                                                 list_of_elements)]))
                return dict_of_elements
        if dict_of_elements == {}:
            return None
        return dict_of_elements
